#pragma once
// Gzipped portal assets embedded in flash (generated by tools/embed_web.py).
#include <cstddef>
#include <cstdint>
#include <string>

namespace net {

struct WebAsset {
  const char* path;
  const char* contentType;
  const uint8_t* data;  // gzip
  size_t size;
  size_t rawSize;
};

const WebAsset* findWebAsset(const std::string& path);
size_t webAssetsTotalBytes();

}  // namespace net
